import { loadFont } from "@remotion/google-fonts/InstrumentSans";
import { loadFont as loadSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import { getLength, getPointAtLength } from "@remotion/paths";
import React, { useEffect, useId, useLayoutEffect, useMemo } from "react";
import { AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig } from "remotion";

// Chrome parks a glyph raster on a whole pixel vertically for as long as the
// matrix that carries it is axis-aligned, so text under a slow transform
// clicks along pixel by pixel. A lean too small to see takes it off that grid.
//
// A transform that carries text is marked, and told when it moves:
//
//   const glide = useGlide();
//   transform: `scale(${s})${glide(moving)}`
//
// The mark changes nothing by itself. After every frame the blocks of text
// under a marked transform get the lean: each about its own centre, and each
// by no more than its size on the screen needs. A card, a hairline or an image
// is fine under a transform as it is, so they stay level.
//
// Text leans while its transform moves, and it keeps the lean at rest when it
// rests off the pixel grid (a scene shown smaller in a player, a camera that
// holds at 1.03): dropping the lean there would snap it to the nearest pixel,
// up to half a pixel in one frame, and picking it up would snap it back. Text
// that rests on the grid loses the lean without moving, so a scene at rest at
// full size is drawn exactly as it would be without any of this.

/**
 * Returns `glide(moving)`: append it to a transform that carries text, with
 * `moving` true on the frames where that transform changes.
 *
 * Everything else lives inside this one closure: the build of Studio
 * elements pastes this file whole into the component that uses it, where a
 * second `LEAN` or `lean` at the top level would collide.
 */
const useGlide = (() => {
  /** What `glide(false)` adds to a transform: an identity matrix, to find it by. */
  const AT_REST = " matrix(1, 0, 0, 1, 0, 0)";
  /** `glide(true)` adds it twice. */
  const MOVING = AT_REST + AT_REST;
  const MARKED = `[style*="${AT_REST.trim()}"]`;
  // Text leaves the grid once the matrix leans x into y by half of 1/1024 in
  // device pixels (Skia rounds the glyph matrix to 1/1024). A fifth over it.
  const LEAN = 0.6 / 1024;
  // Past this the text is a speck on the screen; it is left alone.
  const STEEPEST = 5;
  // How far from a whole pixel text may rest and still count as on the grid:
  // the jump it makes when the lean goes is no bigger than this.
  const ON_GRID = 0.05;

  /** The linear part of a 2D matrix: x' = a·x + c·y, y' = b·x + d·y. */
  type Lin = [a: number, b: number, c: number, d: number];
  const LEVEL: Lin = [1, 0, 0, 1];
  const times = (m: Lin, n: Lin): Lin => [
    m[0] * n[0] + m[2] * n[1],
    m[1] * n[0] + m[3] * n[1],
    m[0] * n[2] + m[2] * n[3],
    m[1] * n[2] + m[3] * n[3],
  ];
  const turned = (degrees: number): Lin => {
    const t = (degrees * Math.PI) / 180;
    return [Math.cos(t), Math.sin(t), -Math.sin(t), Math.cos(t)];
  };
  const offWhole = (n: number) => Math.abs(n - Math.round(n));

  type Block = HTMLElement | SVGTextElement | SVGSVGElement;
  let leant: Block[] = [];
  // Fonts arrive after the first pass and change what is laid out where, with
  // no render to follow: a block or a marked element that changes size is read
  // again before the frame is painted.
  let watcher: ResizeObserver | undefined;
  const watched = new WeakSet<Element>();
  const watch = (el: Element) => {
    if (watched.has(el)) return;
    watched.add(el);
    watcher ??= new ResizeObserver(() => lean());
    watcher.observe(el);
  };

  const depthOf = (el: Element) => {
    let depth = 0;
    for (let up = el.parentElement; up; up = up.parentElement) depth += 1;
    return depth;
  };

  /** The nearest box around a text node that a transform applies to. */
  const blockOf = (node: Node): Block | null => {
    for (let el = node.parentElement; el; el = el.parentElement) {
      if (el instanceof SVGElement) {
        const text = el.closest("text");
        if (!(text instanceof SVGTextElement)) return null;
        // Text that only shapes a mask or a clip is not drawn where it stands
        // and cannot turn by itself: its whole drawing leans for it.
        if (!text.closest("defs, mask, clipPath, pattern, symbol, marker"))
          return text;
        let drawing = text.ownerSVGElement;
        while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
        return drawing;
      }
      if (!(el instanceof HTMLElement)) continue;
      const { display } = getComputedStyle(el);
      if (display !== "inline" && display !== "contents") return el;
    }
    return null;
  };

  /** One pass over the page: what every element's own transforms do. */
  function reader(given: Map<Element, number>) {
    type Own = {
      /** `scale` and `transform`, without the `rotate` property. */
      lin: Lin;
      /** `rotate`, in degrees: a lean given in this pass, or the scene's own. */
      turn: number;
      /** How far down it is moved, and by what whole factor it is scaled from
       * its top left corner; null when it does anything else. */
      carry: { dy: number; k: number } | null;
    };
    const lens = new Map<Element, boolean>();
    /** Whether an element shows its children in perspective. */
    const lensOn = (el: Element | null): boolean => {
      if (!el) return false;
      const seen = lens.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const result =
        style.perspective !== "none" ||
        (style.transformStyle === "preserve-3d" && lensOn(el.parentElement));
      lens.set(el, result);
      return result;
    };
    const own = new Map<Element, Own | null>();
    const ownOf = (el: Element): Own | null => {
      const seen = own.get(el);
      if (seen !== undefined) return seen;
      const style = getComputedStyle(el);
      const m = new DOMMatrixReadOnly(
        style.transform === "none" ? "" : style.transform,
      );
      const scale = style.scale === "none" ? [] : style.scale.split(" ");
      const sx = scale.length ? Number.parseFloat(scale[0]) : 1;
      const sy = scale.length > 1 ? Number.parseFloat(scale[1]) : sx;
      const rotate = style.rotate === "none" ? [] : style.rotate.split(" ");
      let result: Own | null = null;
      // Seen in perspective, text is drawn on a layer of its own: not ours. A
      // turn out of the plane without perspective lands flat on the screen,
      // and text under it snaps like any other.
      // A push along z alone, or a half turn, leaves it flat even under a lens.
      const inPerspective =
        Math.max(Math.abs(m.m14), Math.abs(m.m24), Math.abs(m.m34)) > 1e-9 ||
        (Math.max(
          Math.abs(m.m13),
          Math.abs(m.m31),
          Math.abs(m.m23),
          Math.abs(m.m32),
        ) > 1e-6 &&
          lensOn(el.parentElement));
      if (!inPerspective && rotate.length < 2) {
        // The `scale` property acts on what `transform` has produced.
        const lin: Lin = [m.a * sx, m.b * sy, m.c * sx, m.d * sy];
        const moved =
          style.translate === "none"
            ? 0
            : (style.translate.split(" ")[1] ?? "0px");
        const k = Math.round(lin[0]);
        const whole =
          m.is2D &&
          k >= 1 &&
          Math.abs(lin[0] - k) < 1e-4 &&
          Math.abs(lin[3] - k) < 1e-4 &&
          Math.abs(lin[1]) < 1e-5 &&
          Math.abs(lin[2]) < 1e-5 &&
          rotate.length === 0 &&
          (moved === 0 || moved.endsWith("px")) &&
          // Scaled about its corner, a box stays where layout put it.
          (k === 1 || /^0(px)? 0(px)?/.test(style.transformOrigin));
        result = {
          lin,
          turn: rotate.length ? Number.parseFloat(rotate[0]) : 0,
          carry: whole
            ? { dy: sy * m.f + (moved === 0 ? 0 : Number.parseFloat(moved)), k }
            : null,
        };
      }
      own.set(el, result);
      return result;
    };
    const down = new Map<Element, Lin | null>();
    /** Everything from the page down to and including this element. */
    const linDown = (el: Element | null): Lin | null => {
      if (!el) return LEVEL;
      const seen = down.get(el);
      if (seen !== undefined) return seen;
      const above = linDown(el.parentElement);
      const mine = above && ownOf(el);
      const result =
        above && mine
          ? times(times(above, turned(given.get(el) ?? mine.turn)), mine.lin)
          : null;
      down.set(el, result);
      return result;
    };
    const carried = new Map<Element, { dy: number; k: number } | null>();
    const carryDown = (
      el: Element | null,
    ): { dy: number; k: number } | null => {
      if (!el) return { dy: 0, k: 1 };
      const seen = carried.get(el);
      if (seen !== undefined) return seen;
      const above = carryDown(el.parentElement);
      const mine = above && !given.has(el) ? ownOf(el)?.carry : null;
      const result =
        above && mine
          ? { dy: above.dy + above.k * mine.dy, k: above.k * mine.k }
          : null;
      carried.set(el, result);
      return result;
    };
    return { ownOf, linDown, carryDown };
  }

  /**
   * Whether text in an SVG rests on the grid: it is placed wherever it is told
   * to, so only when it is shown one to one and its baseline happens to land on
   * a whole pixel. `lands` is where its own space lands on the screen.
   */
  function restsOnGrid(text: SVGTextElement, lands: DOMMatrix | null) {
    if (!lands) return false;
    const dpr = window.devicePixelRatio;
    const style = getComputedStyle(text);
    const k = lands.d * dpr;
    const y = text.y.baseVal.numberOfItems
      ? text.y.baseVal.getItem(0).value
      : 0;
    return (
      text.y.baseVal.numberOfItems <= 1 &&
      text.dy.baseVal.numberOfItems === 0 &&
      !text.querySelector("tspan[y], tspan[dy], textPath") &&
      /^(auto|alphabetic)$/.test(style.dominantBaseline) &&
      /^(auto|baseline)$/.test(style.alignmentBaseline) &&
      Math.abs(lands.b) < 1e-6 &&
      Math.abs(lands.c) < 1e-6 &&
      Math.round(k) >= 1 &&
      offWhole(k) < 2e-3 &&
      offWhole((lands.d * y + lands.f) * dpr) < ON_GRID
    );
  }

  /**
   * The angle that takes a block off the grid, given what is above it (`above`)
   * and what its own transform does (`own`), both in device pixels: the lean is
   * a turn between the two. 0 when the block leans enough as it is, null when
   * no sane angle would do.
   */
  function angleFor(above: Lin, own: Lin): number | null {
    // y from x of `above · turn(θ) · own` is p·sin θ + q·cos θ.
    const p = above[3] * own[0] - above[1] * own[1];
    const q = above[1] * own[0] + above[3] * own[1];
    if (Math.abs(q) >= LEAN) return 0;
    if (Math.abs(p) < 1e-9) return null;
    // Along the turn the scene already has, so the two never cancel out.
    const sine = ((q < 0 ? -LEAN : LEAN) - q) / p;
    if (Math.abs(sine) > Math.sin((STEEPEST * Math.PI) / 180)) return null;
    return (Math.asin(sine) * 180) / Math.PI;
  }

  function lean() {
    for (const el of leant) {
      el.style.removeProperty("rotate");
      if (el instanceof SVGElement) el.style.removeProperty("translate");
    }
    leant = [];
    const zones = document.querySelectorAll<HTMLElement | SVGElement>(MARKED);
    if (zones.length === 0) return;
    // Each block of text under a mark, and whether any transform above it moves.
    const blocks = new Map<Block, boolean>();
    // The texts a whole drawing leans for.
    const standsFor = new Map<SVGSVGElement, SVGTextElement[]>();
    for (const zone of zones) {
      const moving = zone.style.transform.includes(MOVING.trim());
      const walker = document.createTreeWalker(zone, NodeFilter.SHOW_TEXT);
      for (let node = walker.nextNode(); node; node = walker.nextNode()) {
        if (!/\S/.test(node.nodeValue ?? "")) continue;
        const block = blockOf(node);
        // A block that turns by a property of its own is left to the scene.
        if (!block || block.style.rotate) continue;
        blocks.set(block, moving || (blocks.get(block) ?? false));
        const text = node.parentElement?.closest("text");
        if (block instanceof SVGSVGElement && text instanceof SVGTextElement)
          standsFor.set(block, [...(standsFor.get(block) ?? []), text]);
      }
      watch(zone);
    }
    for (const block of blocks.keys()) watch(block);
    const dpr = window.devicePixelRatio;
    const scaled = (m: Lin): Lin => [
      m[0] * dpr,
      m[1] * dpr,
      m[2] * dpr,
      m[3] * dpr,
    ];
    // Outer blocks first: a block inside a leaning one takes only what it
    // still lacks, so leans never pile up. Everything is read before anything
    // is written; `given` stands in for the leans not yet on the page.
    const given = new Map<Element, number>();
    const { ownOf, linDown, carryDown } = reader(given);
    const writes: (() => void)[] = [];
    const ordered = [...blocks.keys()].sort((a, b) => depthOf(a) - depthOf(b));
    for (const el of ordered) {
      const moving = blocks.get(el) === true;
      if (el instanceof HTMLElement) {
        const above = linDown(el.parentElement);
        const mine = ownOf(el);
        if (!above || !mine) continue;
        if (!moving) {
          // Layout puts a baseline on a whole pixel wherever the box itself
          // sits, so text is on the grid when the transforms around it only
          // move it by whole pixels and show it one to one (or two, or three).
          const carry = carryDown(el);
          if (
            carry &&
            offWhole(carry.k * dpr) < 2e-3 &&
            offWhole(carry.dy * dpr) < ON_GRID
          )
            continue;
        }
        const angle = angleFor(scaled(above), mine.lin);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      if (el instanceof SVGSVGElement) {
        // A whole drawing: what it does itself is its own transform and the
        // scale of its viewBox, read off where it lands on the screen.
        const above = linDown(el.parentElement);
        const lands = el.getScreenCTM();
        const det = above ? above[0] * above[3] - above[1] * above[2] : 0;
        if (!above || !lands || Math.abs(det) < 1e-12) continue;
        if (
          !moving &&
          (standsFor.get(el) ?? []).every((text) =>
            restsOnGrid(text, text.getScreenCTM()),
          )
        )
          continue;
        const mine = times(
          [above[3] / det, -above[1] / det, -above[2] / det, above[0] / det],
          [lands.a, lands.b, lands.c, lands.d],
        );
        const angle = angleFor(scaled(above), mine);
        if (!angle) continue;
        given.set(el, angle);
        writes.push(() => el.style.setProperty("rotate", `${angle}deg`));
        leant.push(el);
        continue;
      }
      // Its drawing leans as a whole already.
      let drawing = el.ownerSVGElement;
      while (drawing?.ownerSVGElement) drawing = drawing.ownerSVGElement;
      if (drawing && given.has(drawing)) continue;
      // Text in an SVG is placed wherever it is told to, so it is on the grid
      // only when its baseline happens to land on a whole pixel.
      const frame = el.parentNode;
      if (!(frame instanceof SVGGraphicsElement) || el.style.translate)
        continue;
      const outer = frame.getScreenCTM();
      const whole = el.getScreenCTM();
      if (
        !outer ||
        !whole ||
        Math.abs(outer.a * outer.d - outer.b * outer.c) < 1e-12
      )
        continue;
      // What the text element itself does, in the space it is placed in.
      const mine = outer.inverse().multiply(whole);
      if (!moving && restsOnGrid(el, whole)) continue;
      const angle = angleFor(scaled([outer.a, outer.b, outer.c, outer.d]), [
        mine.a,
        mine.b,
        mine.c,
        mine.d,
      ]);
      if (!angle) continue;
      // An SVG element turns about the corner of its drawing. A move brings
      // the turn to the middle of the text instead.
      const box = el.getBBox();
      const [cx, cy] = [box.x + box.width / 2, box.y + box.height / 2];
      const [px, py] = [
        mine.a * cx + mine.c * cy + mine.e,
        mine.b * cx + mine.d * cy + mine.f,
      ];
      const [cos, sin] = [turned(angle)[0], turned(angle)[1]];
      const [tx, ty] = [px - (px * cos - py * sin), py - (px * sin + py * cos)];
      writes.push(() => {
        el.style.setProperty("rotate", `${angle}deg`);
        el.style.setProperty("translate", `${tx}px ${ty}px`);
      });
      leant.push(el);
    }
    for (const write of writes) write();
  }

  const useFrameEffect =
    typeof window === "undefined" ? useEffect : useLayoutEffect;

  function useGlide() {
    // No dependencies: the lean follows whatever this frame laid out.
    useFrameEffect(lean);
    return glide;
  }

  const glide = (moving: boolean) => (moving ? MOVING : AT_REST);

  return useGlide;
})();

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

const { fontFamily: sans } = loadFont("normal", {
  weights: ["400"],
  subsets: ["latin"],
});
const { fontFamily: serif } = loadSerif("italic", {
  weights: ["400"],
  subsets: ["latin"],
});
const manrope = loadManrope("normal", {
  weights: ["600"],
  subsets: ["latin"],
});

/**
 * Beat sheet (30fps, speed 1):
 * 0–16     several noisy traces jitter across a faint scope graticule.
 * 16–74    a sweep crosses left → right; behind it every trace collapses
 *          into one calm sine. 74–90 the sine holds and drifts.
 * 90–110   the sine flattens to a single line and rises to the R's cap.
 * 110–152  the line runs on into the remocn R, tracing its outline from the
 *          top-left corner; the far end retracts. 150–164 the R fills.
 * 160–208  lockup: the R shrinks into the logo and "emocn" slides out of it,
 *          caption follows. 218–250 hold.
 * The resolved signal, the trace and the R fill carry the gradients.sh
 * "beam" palette; noise stays neutral, so colour means signal.
 */

export interface SignalResolveProps {
  /** Letters that slide out of the R at the end ("R" + name = the logo). */
  name?: string;
  /** Last sentence is set in an italic serif. */
  caption?: string;
  /** Number of noisy traces before they resolve. */
  traces?: number;
  accent?: string;
  /** Color of the traces, the name and the serif sentence; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the caption. Load it yourself; Instrument Sans by default. */
  fontFamily?: string;
  /** Frames between caption words as they fade up. */
  stagger?: number;
  /** The scope graticule behind the traces. */
  grid?: boolean;
  /** Size of the scope, lockup and caption, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Film grain over the scene. */
  grain?: boolean;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

/**
 * The real remocn.dev "R" (viewBox 124.06 × 134.26), re-ordered so the
 * outline starts at the top-left corner and runs right along the cap: the
 * incoming line simply continues into it.
 */
const R_TRACE =
  "M 0.01 0 L 41.85 0.04 C 88.09 0.08 83.93 0.01 87.64 0.83 C 101.93 4.02 114.59 15.81 119.44 30.43 C 124.06 44.32 120.59 58.93 109.97 70.36 C 104.15 76.62 96.18 81.72 88.07 84.38 C 86.36 84.94 85.79 85.25 85.09 86 C 83.66 87.53 83.36 89.89 84.39 91.57 C 84.52 91.78 91.91 101.45 100.82 113.07 L 117.01 134.19 L 106.36 134.23 C 98.97 134.26 95.5 134.23 95.06 134.13 C 94.11 133.93 93.52 133.35 92.82 131.97 C 92.5 131.34 92.07 130.59 91.85 130.32 C 91.63 130.04 85.04 122.28 77.2 113.07 C 69.35 103.85 62.52 95.76 62.02 95.07 C 59.67 91.86 56.61 89.56 53.22 88.45 C 50.75 87.65 50.12 87.59 43.57 87.53 C 39.41 87.5 37.23 87.53 36.45 87.63 C 27.86 88.75 21.79 93.65 19.82 101.04 C 19.08 103.82 19.1 103.27 19.05 119.41 L 19 134.26 L 9.5 134.26 L 0 134.26 L 0.04 116.66 C 0.08 103.13 0.12 98.85 0.25 98.13 C 1.3 91.91 4.86 85.68 10.65 79.89 C 14.84 75.7 19.9 72.15 24.18 70.4 C 27.03 69.23 24.82 69.43 55.2 67.69 C 70.18 66.83 82.81 66.07 83.26 66 C 89.68 64.99 94.66 61.96 97.91 57.07 C 102.53 50.1 103.19 38.56 99.38 31.01 C 96.2 24.68 89.89 20.69 81.32 19.57 C 80.02 19.4 76.07 19.36 51.39 19.27 C 23.18 19.16 22.94 19.16 21.7 18.9 C 13.45 17.16 4.91 11.04 1.09 4.13 C 0.36 2.79 0.01 1.73 0.01 0.81 Z";
const VB = { w: 124.06, h: 134.26 };
/** Manrope: baseline sits 0.883em below the top of a line-height-1 box. */
const MANROPE_ASC = 0.883;
const MANROPE_DESC = 0.117;

/** gradients.sh "beam": [#f4f7ff, #8fb4ff, #3d5bff, #1a1660]. */
const BEAM = {
  dark: {
    line: ["#3D5BFF", "#8FB4FF", "#F4F7FF"],
    mark: ["#F4F7FF", "#8FB4FF", "#3D5BFF"],
  },
  light: {
    line: ["#8FB4FF", "#3D5BFF", "#1A1660"],
    mark: ["#8FB4FF", "#3D5BFF", "#1A1660"],
  },
} as const;

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    grid: "rgba(255,255,255,0.055)",
    axis: "rgba(255,255,255,0.1)",
    wash: "rgba(255,255,255,0.045)",
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    grid: "rgba(18,18,20,0.06)",
    axis: "rgba(18,18,20,0.11)",
    wash: "rgba(255,255,255,0.8)",
    grain: 0.045,
  },
} as const;

type Palette = (typeof THEMES)[keyof typeof THEMES];

function hash(n: number) {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
}

/** Smooth 1D value noise in [-1, 1]. */
function noise(x: number, seed: number) {
  const i = Math.floor(x);
  const f = x - i;
  const s = f * f * (3 - 2 * f);
  const a = hash(i * 1.37 + seed * 91.1) * 2 - 1;
  const b = hash((i + 1) * 1.37 + seed * 91.1) * 2 - 1;
  return a + (b - a) * s;
}

function fbm(x: number, seed: number) {
  return (
    noise(x, seed) * 0.6 +
    noise(x * 2.1, seed + 3) * 0.28 +
    noise(x * 4.3, seed + 7) * 0.12
  );
}

function smoothstep(e0: number, e1: number, x: number) {
  const k = Math.max(0, Math.min(1, (x - e0) / (e1 - e0)));
  return k * k * (3 - 2 * k);
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={11}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function Graticule({
  width,
  height,
  cy,
  opacity,
  pal,
  u,
}: {
  width: number;
  height: number;
  cy: number;
  opacity: number;
  pal: Palette;
  u: number;
}) {
  const left = width * 0.07;
  const right = width * 0.93;
  const half = height * 0.3;
  const top = cy - half;
  const bottom = cy + half;
  const cols = 10;
  const rows = 6;
  const lines: React.ReactNode[] = [];
  for (let c = 0; c <= cols; c++) {
    const x = left + ((right - left) * c) / cols;
    lines.push(
      <line
        key={`c${c}`}
        x1={x}
        x2={x}
        y1={top}
        y2={bottom}
        stroke={c === cols / 2 ? pal.axis : pal.grid}
      />,
    );
  }
  for (let r = 0; r <= rows; r++) {
    const y = top + ((bottom - top) * r) / rows;
    lines.push(
      <line
        key={`r${r}`}
        x1={left}
        x2={right}
        y1={y}
        y2={y}
        stroke={r === rows / 2 ? pal.axis : pal.grid}
      />,
    );
  }
  // minor ticks on the axes
  for (let k = 0; k <= cols * 5; k++) {
    const x = left + ((right - left) * k) / (cols * 5);
    lines.push(
      <line
        key={`tx${k}`}
        x1={x}
        x2={x}
        y1={cy - 3 * u}
        y2={cy + 3 * u}
        stroke={pal.axis}
      />,
    );
  }
  for (let k = 0; k <= rows * 5; k++) {
    const y = top + ((bottom - top) * k) / (rows * 5);
    lines.push(
      <line
        key={`ty${k}`}
        x1={width / 2 - 3 * u}
        x2={width / 2 + 3 * u}
        y1={y}
        y2={y}
        stroke={pal.axis}
      />,
    );
  }
  return (
    <g opacity={opacity} strokeWidth={Math.max(1, u)}>
      {lines}
    </g>
  );
}

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function SignalResolve({
  name = "emocn",
  caption = "Less noise. More signal.",
  traces = 5,
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = sans,
  stagger = 3,
  grid = true,
  scale = 1,
  delay = 0,
  grain = true,
  speed = 1,
  theme = "dark",
}: SignalResolveProps) {
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height } = useSceneConfig();
  const u = height / 720;
  const pal = THEMES[theme];
  const fg = ink ?? pal.fg;
  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? pal.bg);
  const knock = transparent ? pal.bg : stage;
  const beam = BEAM[theme];
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  const outlineLen = useMemo(() => getLength(R_TRACE), []);

  const cy = height * 0.45;
  const stroke = 1.35 * u;

  // ── lockup geometry (needed early: the line rises to the R's cap) ─────
  const kTrace = 2.45 * u;
  const fontSize = 124 * u;
  const kLock = (fontSize * 0.76) / VB.h;
  const traceCenter = height * 0.47;
  const lineY = traceCenter - (VB.h * kTrace) / 2;

  // ── scope phase ────────────────────────────────────────────────────────
  const sweepX = interpolate(t, [16, 74], [-0.3 * width, 1.3 * width], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const band = width * 0.24;
  const flat = interpolate(t, [90, 110], [1, 0], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const rise = interpolate(t, [88, 112], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const baseY = cy + (lineY - cy) * rise;
  const sineAmp = height * 0.11 * flat;
  const chaosAmp = height * 0.21;
  const N = Math.round(width / 3.2);

  const clean = (x: number, time: number) =>
    baseY + sineAmp * Math.sin((x / width) * Math.PI * 2 * 2.4 + time * 0.07);

  const tracePath = (i: number, time: number, calm = false) => {
    const sweep = interpolate(time, [16, 74], [-0.3 * width, 1.3 * width], {
      ...CLAMP,
      easing: EASE_IO,
    });
    let d = "";
    for (let k = 0; k <= N; k++) {
      const x = (k / N) * width;
      const xn = x / width;
      const r = calm ? 1 : smoothstep(sweep, sweep - band, x);
      let y = clean(x, time);
      if (r < 1) {
        const chaos =
          fbm(xn * (5 + i * 1.3) + time * (0.05 + i * 0.012), i * 7 + 1) *
            0.62 +
          Math.sin(xn * Math.PI * 2 * (2.6 + i * 1.45) + time * 0.19 + i * 2) *
            0.26 +
          noise(xn * 46 + time * 0.9, i * 13 + 5) * 0.12;
        const yc = cy + chaosAmp * chaos * (1.15 - i * 0.07);
        y = yc + (y - yc) * r;
      }
      d += `${k === 0 ? "M" : "L"}${x.toFixed(1)} ${y.toFixed(1)}`;
    }
    return d;
  };

  const resolved = t >= 76;
  const scopeVisible = t < 110;
  const traceEls: React.ReactNode[] = [];
  if (scopeVisible && !resolved) {
    for (let i = 0; i < traces; i++) {
      const base = 0.9 - (i / Math.max(1, traces)) * 0.5;
      // phosphor persistence: the previous sweeps of the beam linger
      for (const lag of [3.6, 2.4, 1.2, 0]) {
        const o = lag === 0 ? 1 : lag < 2 ? 0.32 : lag < 3 ? 0.15 : 0.07;
        traceEls.push(
          <path
            key={`${i}-${lag}`}
            d={tracePath(i, t - lag)}
            fill="none"
            stroke={fg}
            strokeWidth={stroke}
            strokeLinejoin="round"
            opacity={base * o * 0.75}
          />,
        );
      }
    }
  }

  const gratO =
    interpolate(t, [0, 12], [0.6, 1], CLAMP) *
    interpolate(t, [92, 116], [1, 0], { ...CLAMP, easing: EASE_IO });

  // sweep marker: a hairline and the point where the signal locks
  const sweepOn = t > 16 && t < 74;
  const sweepO =
    interpolate(t, [16, 24], [0, 1], CLAMP) *
    interpolate(t, [64, 74], [1, 0], CLAMP);
  const lockX = sweepX - band * 0.85;
  const lockY = clean(lockX, t);
  // the beam colour paints the signal only where it has resolved
  const paintX = resolved ? width : Math.max(0, sweepX - band * 0.55);

  // ── lockup ────────────────────────────────────────────────────────────
  const lockAt = (f: number) =>
    interpolate(f, [160, 188], [0, 1], {
      ...CLAMP,
      easing: EASE_IO,
    });
  const lock = lockAt(t);
  const k = kTrace + (kLock - kTrace) * lock;
  const markW = VB.w * k;
  const markH = VB.h * k;
  // Where the lockup row sits for a given `lock`. The row is laid out where
  // it lands and rides there by transform all its life: moved by `top`,
  // layout rounds the word's baseline to whole pixels, and handing it back to
  // layout when it lands would jump by that rounding.
  const rowTopAt = (l: number) => {
    const kl = kTrace + (kLock - kTrace) * l;
    const cY = interpolate(l, [0, 1], [traceCenter, height * 0.43]);
    return cY + (VB.h * kl) / 2 - Math.max(VB.h * kl, MANROPE_ASC * fontSize);
  };
  const rowTop = rowTopAt(1);
  // Before the lock the R rests where layout used to round it, on a whole
  // pixel: its top stroke continues the lead line and stays one crisp pixel.
  // The fraction that rounding took is handed back over the move.
  const startDy = Math.round(rowTopAt(0)) - Math.round(rowTop);
  const settle = startDy - (rowTopAt(0) - rowTop);
  const rowDyAt = (f: number) => {
    const l = lockAt(f);
    return rowTopAt(l) - rowTop + (1 - l) * settle;
  };
  const rowDy = rowDyAt(t);
  // The word beside the R also reflows as the R shrinks, so the lean comes a
  // frame before the move and goes a frame after it: never on a frame where
  // layout moves the word too.
  const locking = rowDyAt(t + speed) !== rowDy || rowDyAt(t - speed) !== rowDy;
  const slide = interpolate(t, [176, 204], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const wordClip = interpolate(t, [179, 208], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  // the outline starts at the R's top-left corner, right on the line
  const entryX = width / 2 - (VB.w * kTrace) / 2;

  // ── reel-in: lead line + outline trace ───────────────────────────────
  const reeling = t >= 110;
  const head = interpolate(t, [110, 152], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const tailX = interpolate(t, [112, 150], [0, entryX], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const rightEnd = interpolate(t, [110, 128], [width, entryX], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const fillIn = interpolate(t, [148, 166], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const beamPt =
    head > 0 && head < 1
      ? getPointAtLength(R_TRACE, outlineLen * head)
      : undefined;
  const beamO = interpolate(head, [0, 0.04, 0.94, 1], [0, 1, 1, 0], CLAMP);

  // ── caption: the last sentence turns to an italic serif ───────────────
  const sentences = caption.split(/(?<=[.!?\u2026])\s+/);
  const words: { w: string; serif: boolean }[] = [];
  sentences.forEach((sentence, si) => {
    for (const w of sentence.split(" ")) {
      words.push({
        w,
        serif: sentences.length > 1 && si === sentences.length - 1,
      });
    }
  });
  const word = (i: number) =>
    interpolate(t, [198 + i * stagger, 218 + i * stagger], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });

  const edgeMask = `linear-gradient(90deg, transparent 0%, #000 9%, #000 91%, transparent 100%)`;
  const localStroke = stroke / k;
  const lineGrad = `url(#l${uid})`;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {!transparent ? (
        <AbsoluteFill
          style={{
            background: `radial-gradient(ellipse 60% 50% at 50% 45%, ${pal.wash}, transparent 75%)`,
          }}
        />
      ) : null}

      <ScaleLayer scale={scale}>
        {/* scope */}
        <AbsoluteFill
          style={{
            WebkitMaskImage: reeling ? undefined : edgeMask,
            maskImage: reeling ? undefined : edgeMask,
          }}
        >
          <svg
            width={width}
            height={height}
            viewBox={`0 0 ${width} ${height}`}
            style={{ position: "absolute", inset: 0 }}
            aria-hidden
          >
            <defs>
              <linearGradient id={`h${uid}`} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stopColor={fg} stopOpacity={0} />
                <stop offset="0.5" stopColor={fg} stopOpacity={0.42} />
                <stop offset="1" stopColor={fg} stopOpacity={0} />
              </linearGradient>
              <linearGradient
                id={`l${uid}`}
                gradientUnits="userSpaceOnUse"
                x1={width * 0.05}
                y1={0}
                x2={width * 0.95}
                y2={0}
              >
                <stop offset="0" stopColor={beam.line[0]} />
                <stop offset="0.5" stopColor={beam.line[1]} />
                <stop offset="1" stopColor={beam.line[2]} />
              </linearGradient>
              <linearGradient
                id={`f${uid}`}
                gradientUnits="userSpaceOnUse"
                x1={0}
                y1={0}
                x2={entryX}
                y2={0}
              >
                <stop offset="0" stopColor="#fff" stopOpacity={0} />
                <stop offset="0.4" stopColor="#fff" stopOpacity={0.6} />
                <stop offset="1" stopColor="#fff" stopOpacity={1} />
              </linearGradient>
              <mask id={`m${uid}`} maskUnits="userSpaceOnUse">
                <rect
                  x={0}
                  y={0}
                  width={width}
                  height={height}
                  fill={`url(#f${uid})`}
                />
              </mask>
              <clipPath id={`c${uid}`}>
                <rect x={0} y={0} width={paintX} height={height} />
              </clipPath>
            </defs>
            {grid ? (
              <Graticule
                width={width}
                height={height}
                cy={cy}
                opacity={gratO}
                pal={pal}
                u={u}
              />
            ) : null}
            {traceEls}
            {scopeVisible && paintX > 0 ? (
              <path
                d={tracePath(0, t, true)}
                fill="none"
                stroke={lineGrad}
                strokeWidth={stroke * 1.5}
                strokeLinejoin="round"
                strokeLinecap="round"
                clipPath={`url(#c${uid})`}
              />
            ) : null}
            {sweepOn ? (
              <g opacity={sweepO}>
                <rect
                  x={lockX - 0.5 * u}
                  y={cy - height * 0.3}
                  width={Math.max(1, u)}
                  height={height * 0.6}
                  fill={`url(#h${uid})`}
                />
                <circle
                  cx={lockX}
                  cy={lockY}
                  r={5 * u}
                  fill={accent}
                  stroke={knock}
                  strokeWidth={2 * u}
                />
              </g>
            ) : null}
            {reeling ? (
              <g>
                {/* the far end retracts toward the R */}
                {rightEnd > entryX + 0.5 ? (
                  <line
                    x1={entryX}
                    x2={rightEnd}
                    y1={lineY}
                    y2={lineY}
                    stroke={lineGrad}
                    strokeWidth={stroke * 1.5}
                  />
                ) : null}
                {/* the lead is reeled in; it fades toward its tail */}
                {tailX < entryX - 0.5 ? (
                  <line
                    x1={tailX}
                    x2={entryX}
                    y1={lineY}
                    y2={lineY}
                    stroke={lineGrad}
                    strokeWidth={stroke * 1.5}
                    mask={`url(#m${uid})`}
                  />
                ) : null}
              </g>
            ) : null}
          </svg>
        </AbsoluteFill>

        {/* R + "emocn": the traced R becomes the logo's first letter */}
        {reeling ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: rowTop,
              display: "flex",
              justifyContent: "center",
              transform: `translateY(${rowDy}px)${glide(locking)}`,
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "baseline",
                transform: `translateX(calc(${(1 - slide) * 50}% - ${(1 - slide) * (markW / 2)}px))`,
              }}
            >
              <svg
                width={markW}
                height={markH}
                viewBox={`0 0 ${VB.w} ${VB.h}`}
                style={{ overflow: "visible", flexShrink: 0 }}
                aria-hidden
              >
                <defs>
                  <linearGradient id={`r${uid}`} x1="0" y1="0" x2="0.85" y2="1">
                    <stop offset="0" stopColor={beam.mark[0]} />
                    <stop offset="0.5" stopColor={beam.mark[1]} />
                    <stop offset="1" stopColor={beam.mark[2]} />
                  </linearGradient>
                </defs>
                <path
                  d={R_TRACE}
                  fill={`url(#r${uid})`}
                  fillOpacity={fillIn}
                  stroke={`url(#r${uid})`}
                  strokeWidth={localStroke * 1.5}
                  strokeLinejoin="round"
                  pathLength={1}
                  strokeDasharray={`${head} 2`}
                />
                {beamPt ? (
                  <circle
                    cx={beamPt.x}
                    cy={beamPt.y}
                    r={(3 * u) / k}
                    fill={beam.mark[theme === "dark" ? 0 : 2]}
                    opacity={beamO}
                  />
                ) : null}
              </svg>
              <div
                style={{
                  clipPath: `inset(-20% ${(1 - wordClip) * 100}% -20% 0)`,
                  fontFamily: manrope.fontFamily,
                  fontWeight: 600,
                  fontSize,
                  lineHeight: 1,
                  letterSpacing: "-0.025em",
                  marginLeft: "0.04em",
                  color: fg,
                  paddingRight: 6 * u,
                  transform: `translateX(${(1 - wordClip) * -28 * u}px)`,
                  whiteSpace: "nowrap",
                }}
              >
                {name}
              </div>
            </div>
          </div>
        ) : null}

        {/* caption */}
        <div
          style={{
            position: "absolute",
            left: "12%",
            right: "12%",
            top:
              height * 0.43 +
              (VB.h * kLock) / 2 +
              MANROPE_DESC * fontSize +
              34 * u,
            textAlign: "center",
            fontFamily,
            fontWeight: 400,
            fontSize: 32 * u,
            lineHeight: 1.3,
            letterSpacing: "-0.012em",
            color: pal.muted,
            textWrap: "balance",
          }}
        >
          {words.map(({ w, serif: isSerif }, i) => (
            <span
              key={i}
              style={{
                display: "inline-block",
                whiteSpace: "pre",
                fontFamily: isSerif ? serif : undefined,
                fontStyle: isSerif ? "italic" : undefined,
                fontSize: isSerif ? "1.14em" : undefined,
                letterSpacing: isSerif ? "-0.005em" : undefined,
                color: isSerif ? fg : undefined,
                opacity: word(i),
                transform: `translateY(${(1 - word(i)) * 10 * u}px)${glide(midway(word(i)))}`,
                filter: `blur(${(1 - word(i)) * 4 * u}px)`,
              }}
            >
              {i < words.length - 1 ? `${w} ` : w}
            </span>
          ))}
        </div>
      </ScaleLayer>

      {!transparent && grain ? <Grain opacity={pal.grain} /> : null}
    </AbsoluteFill>
  );
}
